SELECT count(1) FROM ct_lon_contract_withdraw_plan clcwp WHERE 1=1
and clcwp.contract_id = #{contractId}
AND EXISTS ( SELECT 1 FROM ct_lon_contract_repayment_plan clcrp WHERE clcrp.withdraw_plan_id = clcwp.withdraw_plan_id )

SELECT lc.*, hbm.bp_name credit_bp_name , hbm.extra_nam , (select scv.MEANING from sys_code_b sc,sys_code_value_b scv where sc.CODE_ID = scv.CODE_ID and sc.CODE = 'LON.CREDIT_CATEGORY' and scv.value = lc.document_type) document_type_desc, case when lc.con_release_flag='Y' then (lc.FINANCE_AMOUNT-nvl(withdraw.surplus_amount,0)) else (lc.FINANCE_AMOUNT-nvl(withdraw.due_amount,0)) end remaining_amount, nvl(withdraw.due_amount,0) used_withdraw_amount, ( SELECT hds.description FROM hls_document_status hds WHERE hds.document_category = 'LON_CONTRACT' AND hds.enabled_flag = 'Y' AND hds.status_code = lc.settle_status ) settle_status_desc, (select fc.company_short_name from fnd_company fc where fc.company_id = lon_company_id) lon_company_id_desc, (SELECT fc.currency_name FROM fnd_currency fc WHERE fc.currency_code = lc.currency) currency_name, (select min(lcw.due_date) from lon_contract_withdraw lcw where lcw.contract_id=lc.contract_id and lcw.approval_date=withdraw.approval_date) withdraw_start_date, (select max(lcw.withdraw_end_date) from lon_contract_withdraw lcw where lcw.contract_id=lc.contract_id and lcw.approval_date=withdraw.approval_date) withdraw_end_date FROM lon_contract lc left join hls_bp_master hbm on hbm.bp_id = lc.credit_bp_id left join ( select lcw.contract_id, max(lcw.approval_date) approval_date, sum(lcw.due_amount) due_amount, sum(lcw.due_amount-nvl(lr.write_off_amount,0)) surplus_amount from lon_contract_withdraw lcw left join ( select lcr.withdraw_id, nvl(sum(lcr.write_off_amount),0) write_off_amount from lon_contract_repayment lcr where lcr.cf_item=301 group by lcr.withdraw_id) lr on lcw.withdraw_id=lr.withdraw_id where lcw.data_class='NORMAL' and lcw.withdraw_status in('APPROVED','PENDING') group by lcw.contract_id ) withdraw on withdraw.contract_id=lc.contract_id
lc.data_class='NORMAL' and lc.company_id=#{request.companyId}
AND lc.contract_status = #{contractStatus}
AND lc.settle_status = #{settleStatus}
AND lc.contract_id = #{contractId}
AND lc.contract_number LIKE CONCAT(concat('%',#{contractNumber}),'%')
AND lc.contract_name LIKE CONCAT(concat('%',#{contractName}),'%')
and ((lc.contract_number like concat(concat('%',#{params}),'%')) or (lc.contract_name like concat(concat('%',#{params}),'%')) or (lc.major_contract_number like concat(concat('%',#{params}),'%')) or (hbm.extra_nam like concat(concat('%',#{params}),'%')) )
ORDER BY lc.contract_number DESC

select * from ( SELECT lc.FINANCING_TERM_FROM, lc.FINANCING_TERM_TO, LC.DESCRIPTION, LC.ORIGINAL_CONTRACT_NUMBER, LC.CREDIT_CONTRACT_ID,
LC.CREDIT_BP_ID,
LC.DOCUMENT_TYPE, LC.CURRENCY, (select fc.currency_name from fnd_currency fc where fc.currency_code =LC.CURRENCY) currency_n, LC.FINANCE_AMOUNT, LC.CREATED_BY, (select t.DESCRIPTION from sys_user t where t.user_id=lc.CREATED_BY) CREATED_BY_n,
( SELECT fc.company_short_name FROM fnd_company fc WHERE fc.company_id = lc.lon_company_id ) lon_company_id_n, ( SELECT m.BP_NAME FROM hls_bp_master m WHERE m.bp_id = lc.CREDIT_BP_ID ) CREDIT_BP_ID_n, ( SELECT scvb.meaning AS value_name FROM sys_code_value_b scvb, sys_code_b scb WHERE scb.CODE = 'FIN.CREDIT_METHOD' AND scb.code_id = scvb.code_id AND scvb.enabled_flag = 'Y' AND scvb. VALUE != 'F15' AND scvb. VALUE = lc.document_type
) document_type_n, lc.CONTRACT_ID, lc.COMPANY_ID, lc.CONTRACT_VALUE,
lc.DOCUMENT_CATEGORY, lc.BUSINESS_TYPE, lc.CONTRACT_NUMBER, lc.CONTRACT_NAME, lc.CONTRACT_STATUS, lc.CREDIT_FLAG, lc.MORTGAGE_FLAG, lc.ASSURE_FLAG, lc.PLEDGE_FLAG, lc.GUARANTEE_FLAG, lc.LON_COMPANY_ID, lc.DATA_CLASS, lc.RELE_CREDIT_FLAG, lc.BAIL_FLAG, lc.TRANSFER_FLAG, lc.CON_RELEASE_FLAG, lc.CAPITAL_SOURCE, lc.CONTRACT_TYPE_INOUT, lc.OTHER_FLAG, lc.GZ_PLEDGE_FLAG, lc.RETURNED_AMOUNT, lc.CON_EXCHANGE_RATE, lc.CNY_FINANCE_AMOUNT, lc.COPY_INOUT_FLAG, lc.HISTORY_FLAG, lc.SERIAL_NUMBER, lc.CONFIRM_STATUS,LC.NOTE, ( SELECT scvb.meaning AS value_name FROM sys_code_value_b scvb, sys_code_b scb WHERE scb.CODE = 'LON_CONTRACT_STATUS' AND scb.code_id = scvb.code_id AND scvb.enabled_flag = 'Y'
AND scvb. VALUE = lc.contract_status
) contract_status_n, (SELECT M.CREDIT_CON_NUMBER FROM lon_credit_contract M WHERE M.credit_contract_id =LC.CREDIT_CONTRACT_ID) CREDIT_CONTRACT_ID_N, (SELECT m.date_from FROM lon_credit_contract m WHERE m.credit_contract_id = LC.CREDIT_CONTRACT_ID) date_from, (SELECT m.date_to FROM lon_credit_contract m WHERE m.credit_contract_id = LC.CREDIT_CONTRACT_ID) date_to, lc.DEPOSIT_FLAG, nvl((SELECT sum(nvl(d.DUE_AMOUNT, 0)) FROM lon_contract_withdraw d WHERE d.WITHDRAW_STATUS = 'APPROVED' and d.contract_id = lc.contract_id),0)DUE_AMOUNT, (lc.FINANCE_AMOUNT - nvl((SELECT sum(nvl(d.DUE_AMOUNT, 0)) FROM lon_contract_withdraw d WHERE d.WITHDRAW_STATUS = 'APPROVED' and d.contract_id = lc.contract_id),0))fin_due_amount, lc.creation_date FROM lon_contract lc) tc
tc.DATA_CLASS = 'NORMAL'
AND tc.contract_id = #{contractId}
AND tc.contract_number LIKE CONCAT(concat('%',#{contractNumber}),'%')
AND tc.credit_bp_id_n LIKE CONCAT(concat('%',#{creditBpIdN}),'%')
AND tc.contract_status_n = #{contractStatusN}
AND tc.contract_status LIKE CONCAT(concat('%',#{contractStatus}),'%')
AND tc.lon_company_id_n = #{lonCompanyIdN}
AND tc.document_type_n = #{documentTypeN}
AND tc.currency_n = #{currencyN}
AND to_char(tc.financing_term_from, 'YYYY-MM-DD') >= #{financingTermFrom}
AND to_char(tc.financing_term_to, 'YYYY-MM-DD') <= #{financingTermTo}
ORDER BY tc.creation_date DESC

SELECT lc.*, (select hbm.bp_name from hls_bp_master hbm where hbm.bp_id = lc.credit_bp_id) credit_bp_name, ( select sc.code_value_name from
sc where sc.CODE = 'LON.CREDIT_CATEGORY' and sc.code_value=lc.document_type ) document_type_desc, ( SELECT hds.description FROM hls_document_status hds WHERE hds.document_category = 'LON_CONTRACT' AND hds.enabled_flag = 'Y' AND hds.status_code = lc.contract_status ) contract_status_desc, ( SELECT hds.description FROM hls_document_status hds WHERE hds.document_category = 'LON_CONTRACT' AND hds.enabled_flag = 'Y' AND hds.status_code = lc.settle_status ) settle_status_desc, lcc.credit_contract_name, lcc.credit_con_number, (select fc.company_short_name from fnd_company fc where fc.company_id = lc.lon_company_id) lon_company_id_desc, lc.financing_channel, (select scvb.DESCRIPTION from sys_code_b scb,sys_code_value_b scvb where scb.CODE = 'LON.FINANCING_CHANNEL' and scb.CODE_ID = scvb.CODE_ID and scvb.VALUE =lc.financing_channel) financing_channel_desc, lc.domestic_oversea_finance, (select scvb.DESCRIPTION from sys_code_b scb,sys_code_value_b scvb where scb.CODE = 'LON.DOMESTIC_OVERSEA_FINANCE' and scb.CODE_ID = scvb.CODE_ID and scvb.VALUE =lc.domestic_oversea_finance) domestic_oversea_finance_desc, clccr.req_date FROM lon_contract lc, join ct_lon_contract_change_req clccr on clccr.change_req_id = lc.contract_id left join hls_credit_line hcl on hcl.credit_line_id = lc.credit_line_id left join lon_credit_contract_line lccl on lccl.credit_line_id=hcl.credit_line_id left join lon_credit_contract lcc on lcc.credit_contract_id = lccl.credit_contract_id
1=1
AND lc.contract_number LIKE CONCAT(concat('%',#{contractNumber}),'%')
AND lc.contract_name LIKE CONCAT(concat('%',#{contractName}),'%')
AND lc.document_type in
#{item}
AND lc.contract_status in
#{item}
AND lc.currency in
#{item}
AND lc.financing_channel in
#{item}
AND lc.domestic_oversea_finance in
#{item}
AND clccr.req_date >=to_date(#{reqDateFrom},'YYYY-MM-DD')
AND clccr.req_date <=to_date(#{reqDateTo},'YYYY-MM-DD')
AND lc.finance_amount >=#{amtFrom}
AND lc.finance_amount <=#{amtTo}
AND exists (select hbm.bp_name from hls_bp_master hbm where hbm.bp_id = lc.credit_bp_id and hbm.bp_name LIKE CONCAT(concat('%',#{creditBpName}),'%'))
AND lcc.credit_contract_name LIKE CONCAT(concat('%',#{creditContractName}),'%')
and lcc.credit_con_number LIKE CONCAT(concat('%',#{creditConNumber}),'%')
ORDER BY lc.LAST_UPDATE_DATE DESC

