SELECT lc.* , hbm.bp_name credit_bp_name , hbm.extra_nam, hbm.rele_com_flag, hbm.bp_code, hbm.domestic_oversea, hbm.local_nonlocal, lc.original_contract_number , lc.finance_amount , lc.credit_contract_id , oldcre.credit_contract_name, oldcre.credit_con_number, lcc.withdraw_perequisite, lcc.post_loan_manage, ( select sc.code_value_name from
sc where sc.CODE = 'LON.CREDIT_CATEGORY' and sc.code_value=lcc.document_type ) document_type_desc, hcl.document_type document_type2, lccl.credit_category, lccl.withdraw_deadline, hcl.credit_line_amt, calc.actual_available_amt open_to_buy, nvl(calc.credit_exposure_amt , 0) credit_exposure_amt, nvl(calc.withdraw_balance,0) withdraw_balance, hcl.valid_from, hcl.valid_to, hcl.first_withdraw_date, hcl.delay_from, hcl.delay_to, hcl.competent_dept, hcl.finance_type, lc.credit_line_id , ( SELECT hdt.description FROM hls_document_type hdt WHERE hdt.document_category = hcl.document_category AND hdt.document_type = hcl.document_type AND hdt.business_type = hcl.business_type ) credit_line_desc , cba.bank_account_name withdraw_bank_account_name , cba.bank_account_num withdraw_bank_account_number , cba.bank_account_name repayment_bank_account_name , cba.bank_account_num repayment_bank_account_number , ( SELECT ca.bank_name FROM csh_bank ca WHERE ca.bank_id = cba.bank_id) withdraw_bank_name, cba.bank_branch_name withdraw_bank_branch_name, lcc.currency credit_currency_code, (SELECT fc.currency_name FROM fnd_currency fc WHERE fc.currency_code = lc.currency) currency_name, nvl(withdraw.due_amount,0) withdraw_approved_amount, case when lc.con_release_flag='Y' then (lc.finance_amount - nvl(withdraw.surplus_amount,0)) else (lc.finance_amount - nvl(withdraw.due_amount,0)) end withdraw_left_amount FROM lon_contract lc left join hls_credit_line hcl on hcl.credit_line_id = lc.credit_line_id left join lon_credit_line_calc calc on calc.credit_line_id = hcl.credit_line_id left join lon_credit_contract_line lccl on lccl.credit_line_id=hcl.credit_line_id left join lon_credit_contract lcc on lcc.credit_contract_id = lccl.credit_contract_id left join lon_credit_contract oldcre on oldcre.credit_contract_id=lc.credit_contract_id left join hls_bp_master hbm on hbm.bp_id = lc.credit_bp_id left join csh_bank_account cba on cba.bank_account_id = lc.repayment_bank_account_id left join ( select lcw.contract_id, sum(lcw.due_amount) due_amount, sum(lcw.due_amount-nvl(lr.write_off_amount,0)) surplus_amount from lon_contract_withdraw lcw left join ( select lcr.withdraw_id, nvl(sum(lcr.write_off_amount),0) write_off_amount from lon_contract_repayment lcr where lcr.cf_item=301 group by lcr.withdraw_id) lr on lcw.withdraw_id=lr.withdraw_id where lcw.data_class='NORMAL' and lcw.withdraw_status in('APPROVED','PENDING') group by lcw.contract_id ) withdraw on withdraw.contract_id=lc.contract_id
1=1
